import{_ as t,a,b as i,c as s}from"./chunks/package-import-297.C0Lrc5sP.js";import{_ as r,o,c as n,a3 as d}from"./chunks/framework.BlfGB29P.js";const f=JSON.parse('{"title":"Devices and tablets","description":"Device tiles, floorplan markers, tablet return and package capabilities in Studio 0.1.297.","frontmatter":{"title":"Devices and tablets","description":"Device tiles, floorplan markers, tablet return and package capabilities in Studio 0.1.297."},"headers":[],"relativePath":"en/projects/grafik-visual-studio/devices-tablet.md","filePath":"en/projects/grafik-visual-studio/devices-tablet.md","lastUpdated":1794686592000}'),l={name:"en/projects/grafik-visual-studio/devices-tablet.md"};function c(p,e,h,g,m,u){return o(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="devices-and-tablets" tabindex="-1">Devices and tablets <a class="header-anchor" href="#devices-and-tablets" aria-label="Permalink to &quot;Devices and tablets&quot;">​</a></h1><p><strong>Studio 0.1.297</strong> adds the built-in <strong>Devices</strong> palette set. No additional package installation is required. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.297" target="_blank" rel="noreferrer">GitHub update</a>.</p><h2 id="add-devices" tabindex="-1">Add devices <a class="header-anchor" href="#add-devices" aria-label="Permalink to &quot;Add devices&quot;">​</a></h2><p>Expand the set, drag a widget onto the canvas and select its HA entity in the properties. <strong>Switch, dimmer, color light, thermostat and measurement</strong> each offer a <strong>tile</strong> and a <strong>floorplan marker with popup</strong>: ten entries in total. Position and size remain freely adjustable; this is not an automatic responsive grid. The five standard CSS groups are available, with new optional groups disabled. Widget language: DE/EN/FR; general Studio interface: DE/EN.</p><p><img src="'+t+'" alt="Device tiles and floorplan markers, local demo"></p><div class="ugso-table-scroll" tabindex="0"><table><thead><tr><th>Widget</th><th>Source and controls</th></tr></thead><tbody><tr><td>Switch</td><td><code>switch</code>, <code>light</code> or <code>input_boolean</code>; on/off</td></tr><tr><td>Dimmer</td><td><code>light</code>; brightness only with the corresponding HA capability</td></tr><tr><td>Color light</td><td><code>light</code>; on/off, brightness and RGB according to supported color modes</td></tr><tr><td>Thermostat</td><td><code>climate</code>; a single temperature setpoint within native limits/step size</td></tr><tr><td>Measurement</td><td>State and unit; read-only</td></tr></tbody></table></div><p>Runtime only offers controls supported by the entity. <strong>Read only</strong> prevents writes. The editor never operates devices; unavailable entities are disabled. Server validation remains active. An accepted request does not prove physical device feedback. Continue using <a href="./ha-quellen-climate">Technic/Climate</a> for advanced features such as temperature ranges.</p><h2 id="tablet-return-and-home-page" tabindex="-1">Tablet return and home page <a class="header-anchor" href="#tablet-return-and-home-page" aria-label="Permalink to &quot;Tablet return and home page&quot;">​</a></h2><p>In <strong>Settings → General</strong>, <strong>Refresh states on tablet return</strong> refreshes HA values when the page becomes visible again, is restored or regains network connectivity. This does not reload the whole page. Browser/tablet timers may be suspended in the background; returning to the page accounts for this.</p><p><strong>Home page after inactivity</strong> and <strong>Inactivity home page</strong> choose the delay and a visible target page in the current project. <strong>0 seconds = off</strong>, the default. Open dialogs, pending writes and active editing postpone automatic navigation. Kiosk settings and access rights are unchanged.</p><p><img src="'+a+'" alt="Device view at 1280 × 800, local demo"></p><p><img src="'+i+'" alt="Light popup in tablet view, local demo"></p><h2 id="live-heading-values" tabindex="-1">Live heading values <a class="header-anchor" href="#live-heading-values" aria-label="Permalink to &quot;Live heading values&quot;">​</a></h2><p>Border and device headings can optionally display an HA state or attribute, with decimals and a unit. Select the entity and optional attribute in the corresponding property group. Existing headings remain intact; HA values are inserted as text.</p><h2 id="renderers-and-package-capabilities" tabindex="-1">Renderers and package capabilities <a class="header-anchor" href="#renderers-and-package-capabilities" aria-label="Permalink to &quot;Renderers and package capabilities&quot;">​</a></h2><p>Devices, weather, heating rooms, window overview, landlord notification, Technic status lists and Material color schemes load renderers on demand. Shared editor modules remain normally loaded. Concurrent requests share one load.</p><p>Installed package manifests are checked every <strong>30 seconds</strong> and on return. Changes refresh the palette without restarting. This does not automatically install offered catalog updates. Invalid replacements retain the previous catalog; removed definitions stay in memory for already open projects but disappear from the palette for new widgets. Projects are not automatically migrated. See <a href="./widget-packages">package installation</a>.</p><p>Manifest <code>optionalCapabilities</code> is an optional declaration: <code>entity-state</code>, <code>history</code>, <code>light-color</code>, <code>climate</code>. The package list indicates support. Unknown capabilities grant no permissions. Old manifests remain valid; actual controls still depend on HA and entity capabilities.</p><p><img src="'+s+'" alt="Package import with two widgets and capability reporting on the ARM test system (Pi 5)"></p><h2 id="verification-and-limits" tabindex="-1">Verification and limits <a class="header-anchor" href="#verification-and-limits" aria-label="Permalink to &quot;Verification and limits&quot;">​</a></h2><p>On <strong>8 November 2026</strong>, <strong><a href="/en/collection/test-systems#testsystem-arm">ARM test system (Pi 5)</a> / HA 2026.11.0 / Raspberry Pi 5 ARM64</strong> and <strong><a href="/en/collection/test-systems#testsystem-pc">PC (64) test system</a> / HA 2026.10.4 / Proxmox amd64</strong> passed project save/reload, actual operation of a disposable HA helper with state feedback and inactivity return. On the ARM test system (Pi 5), the marker dialog and manual local package import 1.1.0 with two widgets and capability reporting were also checked. The test package and helpers were then removed; inactivity was reset to 0 seconds. Studio stays installed on both systems, preserving existing projects/settings.</p><p>Brightness, RGB and thermostat were tested with local simulated entities. The new views were inspected in a desktop browser at 1440 × 1000 and tablet viewport 1280 × 800. This does not verify physical tablet hardware or every lamp/heating type. 394 JavaScript and 109 Python checks passed, plus 7 focused JavaScript and 17 package Python checks. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/devices-tablet-0.1.297.md" target="_blank" rel="noreferrer">Technical test report</a>.</p><p>Independent HA implementation without copied VIS-2 code or artwork. Web Components and a responsive grid container remain separate future projects.</p>',23)])])}const y=r(l,[["render",c]]);export{f as __pageData,y as default};
